679→/** Human-readable summary. */
680→export function summarize(events) {
681→  const counts = { self: 0, cross_agent: 0, cross_user: 0, unknown: 0 };
682→  const tiers = {};
683→  const assets = new Set();
684→  let excluded = 0;
685→
686→  for (const e of events) {
687→    counts[e.relation] = (counts[e.relation] ?? 0) + 1;
688→    tiers[e.observation] = (tiers[e.observation] ?? 0) + 1;
689→    if (e.asset_id) assets.add(e.asset_id);
690→    if (e.excluded_by_snapshot) excluded += 1;
691→  }
692→
693→  const attributable = events.filter((e) => e.relation !== "unknown").length;
694→  return {
695→    total: events.length,
696→    relations: counts,
697→    tiers,
698→    distinctAssets: assets.size,
699→    excludedBySnapshot: excluded,
700→    crossUserRate: attributable > 0 ? counts.cross_user / attributable : null,
701→    offeredNotRetrieved: events.offeredNotRetrieved ?? [],
702→    unpairedResponses: events.unpairedResponses ?? [],
703→    unknownAssets: events.unknownAssets ?? [],
704→  };
705→}
706→
707→export function renderSummary(s) {
708→  const lines = [
709→    "# Provenance summary",
710→    "",
711→    `${s.total} event(s) across ${s.distinctAssets} asset(s)`,
712→    "",
713→    "| relation | count | meaning |",
714→    "|---|---|---|",
715→    `| self | ${s.relations.self} | used one's own asset; not team value |`,
716→    `| cross_agent | ${s.relations.cross_agent} | same person, different agent |`,
717→    `| cross_user | ${s.relations.cross_user} | another identity used it — this is team value |`,
718→    `| unknown | ${s.relations.unknown} | identity missing on one side; undecidable |`,
719→    "",
720→    "| observation | count |",
721→    "|---|---|",
722→    ...Object.entries(s.tiers).sort().map(([k, v]) => `| ${k} | ${v} |`),
723→    "",
724→  ];
725→
726→  if (s.crossUserRate === null) {
727→    lines.push("Cross-person reuse rate: **not computable** (no event has both identities).");
728→  } else {
729→    lines.push(`Cross-person reuse rate: **${(s.crossUserRate * 100).toFixed(1)}%** (cross_user / attributable events).`);
730→    if (s.relations.cross_user === 0) {
731→      lines.push("");
732→      lines.push("Zero here is a finding, not an omission: the system has **never produced");
733→      lines.push("a single cross-person reuse record**. It logs who created an asset but never");
734→      lines.push("logs whose asset someone else successfully used.");
735→    }
736→  }
737→  const offered = s.offeredNotRetrieved ?? [];
738→  if (offered.length > 0) {
739→    lines.push("", `${offered.length} asset/session pair(s) appeared in the capture but were never retrieved:`);
740→    for (const o of offered) lines.push(`  - ${o.asset_id} via ${o.endpoints.join(", ") || "no bridge command"}`);
741→    lines.push("Offered, not fetched. These are **not** written as `fetched` — appearing in a");
742→    lines.push("listing is the retrieval system doing its job, not the model taking the content.");
743→    lines.push("They are recorded as `recalled` / `injected` by build-early-events.mjs.");
744→  }
745→  const unknownAssets = s.unknownAssets ?? [];
746→  if (unknownAssets.length > 0) {
747→    lines.push("", `**${unknownAssets.length} asset(s) were retrieved that the frozen snapshot does not hold:**`);
748→    for (const u of unknownAssets) {
749→      lines.push(`  - ${u.asset_id} ${u.name ? `(${u.name}) ` : ""}v${u.version ?? "?"}, first at message ${u.first_index}`);
750→    }
751→    lines.push("The pool moved after it was frozen — most likely the system auto-extracted a skill");
752→    lines.push("from a finished session. Nothing above attributes to these assets, and nothing");
753→    lines.push("above *screens* against them either; the judge's earliest-delivery rule does. If");
754→    lines.push("one of them carried a token before a credited fetch, that token's use is not");
755→    lines.push("evidence for the credited asset.");
756→  }
757→  const unpaired = s.unpairedResponses ?? [];
758→  if (unpaired.length > 0) {
759→    lines.push("", `${unpaired.length} response(s) could not be paired with a service-side row:`);
760→    for (const u of unpaired) lines.push(`  - ${u.asset_id}: ${u.responses} response(s), ${u.service_rows} row(s) — ${u.note}`);
761→    lines.push("Left unpaired rather than matched by position. Borrowing another call's row");
762→    lines.push("would give one event evidence it did not earn and report the other as a gap.");
763→  }
764→  if (s.excludedBySnapshot > 0) {
765→    lines.push("", `${s.excludedBySnapshot} event(s) excluded: asset created after the pool was frozen (answer-leak guard).`);
766→  }
767→  return lines.join("\n");
768→}
